CREATE TABLE public.application_scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, target text NOT NULL, commit_sha text NOT NULL, status text NOT NULL DEFAULT 'complete', graph jsonb NOT NULL, reports jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.application_scans TO authenticated; GRANT ALL ON public.application_scans TO service_role; ALTER TABLE public.application_scans ENABLE ROW LEVEL SECURITY; CREATE POLICY owner_read_application_scans ON public.application_scans FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE INDEX application_scans_owner_time ON public.application_scans(user_id, created_at DESC);